let temperatura = context.get("temperatura") || 5;
let humedad = context.get("humedad") || 65;

// Simulaci?n de peque?as variaciones
temperatura += (Math.random() - 0.5) * 2;
humedad += (Math.random() - 0.5) * 2;

// Establecer los l?mites
