    }
];

return msg;

// Valores anteriores del sensor
let temperatura = context.get("temperatura") ?? 23;
let humedad = context.get("humedad") ?? 50;
let luminosidad = context.get("luminosidad") ?? 250;

// Variaciones peque?as para simular un sensor real
temperatura += (Math.random() - 0.5) * 0.6;
humedad += (Math.random() - 0.5) * 2;
luminosidad += (Math.random() - 0.5) * 20;

// L?mites razonables de simulaci?n
temperatura = Math.max(18, Math.min(30, temperatura));
humedad = Math.max(30, Math.min(70, humedad));
luminosidad = Math.max(100, Math.min(500, luminosidad));

// Guardar valores para la siguiente lectura
context.set("temperatura", temperatura);
context.set("humedad", humedad);
context.set("luminosidad", luminosidad);

// Presencia simulada
const presencia = Math.random() > 0.5;

// C?digo de la exhibici?n y sensor
const exhibicionCodigo = "EXP-001";
const sensorCodigo = "SENSOR-001";

// Construir mensaje
msg.topic = `museo/exhibiciones/${exhibicionCodigo}/sensor`;

msg.payload = {
    sensorCodigo: sensorCodigo,
    exhibicionCodigo: exhibicionCodigo,
    presencia: presencia,
    temperatura: Number(temperatura.toFixed(2)),
    humedad: Number(humedad.toFixed(2)),
    luminosidad: Math.round(luminosidad),
    timestamp: new Date().toISOString()
};

return msg;

const timestamp = new Date().toISOString();
const ahoraMs = Date.now();

function uuid() { return crypto.randomUUID(); }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function red(v, d) { const f = Math.pow(10, d); return Math.round(v * f) / f; }
function entre(a, b) { return a + Math.random() * (b - a); }

// Hora efectiva: "horario de visita forzado" hace que el simulador se
// comporte como si fueran las 11:00 (util para demostrar de noche).
const horarioForzado = context.get('horarioForzado') === true;
const horaEfectiva = horarioForzado ? 11 : new Date().getHours();
const abierto = horaEfectiva >= 9 && horaEfectiva < 18;

// Ciclo diario suave: maximo hacia las 15:00, minimo hacia las 03:00.
const ciclo = Math.cos(((horaEfectiva - 15) / 24) * 2 * Math.PI);

// ------------------------------------------------------------------
// 6 sensores ambientales (uno por sala). La identidad es SOLO
// sensorCodigo; el backend resuelve la sala. Los valores base estan
// DENTRO del rango ideal real de cada sala (visto en PostgreSQL), de
// modo que sin escenarios NINGUNA sala queda fuera de rango.
//   Sala 1 Pintura historica : 18-22 C, 45-55 %, luz <=150 (pinturas)
//   Sala 2 Ceramica          : 18-26 C, 35-65 %, luz <=300
//   Sala 3 Patrimonio        : 18-24 C, 40-60 %, luz <=200
//   Sala 4 Historia natural  : 18-24 C, 40-60 %, luz <=150 (textiles)
//   Sala 5 Escultura         : 18-24 C, 40-60 %, luz <=200
//   Sala 6 Civilizaciones    : 18-24 C, 40-60 %, luz <=200
// Base + ciclo + ruido pequeno, con reversion a la media (no random
// walk libre). Margenes amplios respecto a cada limite.
const sensoresAmbientales = [
    { sensorCodigo: 'SENSOR-AMBIENTAL-001', temp: 20.0, hum: 49.0, luzDia: 110, tempAmp: 0.55, humAmp: 1.2, luzMin: 50,  luzMax: 135 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-002', temp: 21.0, hum: 50.0, luzDia: 215, tempAmp: 0.60, humAmp: 1.5, luzMin: 150, luzMax: 245 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-003', temp: 21.0, hum: 50.0, luzDia: 165, tempAmp: 0.60, humAmp: 1.5, luzMin: 90,  luzMax: 190 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-004', temp: 20.5, hum: 48.0, luzDia: 115, tempAmp: 0.55, humAmp: 1.4, luzMin: 50,  luzMax: 140 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-005', temp: 20.0, hum: 47.0, luzDia: 165, tempAmp: 0.55, humAmp: 1.4, luzMin: 80,  luzMax: 190 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-006', temp: 21.0, hum: 49.0, luzDia: 170, tempAmp: 0.60, humAmp: 1.4, luzMin: 90,  luzMax: 190 }
];

// Reversion a la media: cada ciclo el valor se acerca al objetivo y se le
// suma un ruido pequeno. No hay paseo aleatorio libre, asi que no se
// "escapa" del rango con el tiempo.
const K_REVERSION = 0.35;
const RUIDO_TEMP = 0.06;
const RUIDO_HUM = 0.25;
const RUIDO_LUZ = 4;

const msgs = [];

for (const s of sensoresAmbientales) {
    const objT = s.temp + s.tempAmp * ciclo;
    const objH = s.hum + s.humAmp * ciclo;
    // Luz: encendida en horario de museo con una rampa suave de 9 a 10 h;
    // casi 0 fuera de horario.
    let factorLuz = 0;
    if (abierto) {
        factorLuz = horaEfectiva === 9 ? 0.5 : 1;
    }
    const objetivoL = abierto
        ? clamp(s.luzDia * factorLuz + entre(-8, 8), s.luzMin, s.luzMax)
        : entre(0, 3);

    const kT = 'temp_' + s.sensorCodigo;
    const kH = 'hum_' + s.sensorCodigo;
    const kL = 'lum_' + s.sensorCodigo;

    const prevT = context.get(kT);
    const prevH = context.get(kH);
    const prevL = context.get(kL);

    const t = prevT === undefined || prevT === null
        ? objT
        : prevT + (objT - prevT) * K_REVERSION + entre(-RUIDO_TEMP, RUIDO_TEMP);
    const h = prevH === undefined || prevH === null
        ? objH
        : prevH + (objH - prevH) * K_REVERSION + entre(-RUIDO_HUM, RUIDO_HUM);
    const l = prevL === undefined || prevL === null
        ? objetivoL
        : prevL + (objetivoL - prevL) * (abierto ? 0.6 : 0.9) + entre(-RUIDO_LUZ, RUIDO_LUZ);

    const tf = red(clamp(t, 19.0, 21.8), 2);
    const hf = red(clamp(h, 45.2, 52.4), 2);
    const lf = red(clamp(l, 0, s.luzMax), 2);

    context.set(kT, tf);
    context.set(kH, hf);
    context.set(kL, lf);

    msgs.push({
        topic: 'museo/sensores/ambiental',
        payload: {
            mensajeId: uuid(),
            sensorCodigo: s.sensorCodigo,
            temperatura: tf,
            humedad: hf,
            luminosidad: lf,
            timestamp: timestamp
        }
    });
}

// ------------------------------------------------------------------
// 12 sensores de presencia (uno por exhibicion). Cada exhibicion tiene
// un peso de popularidad distinto; la presencia dura entre 20 s y 2 min,
// por lo que NO cambia en cada ciclo de 5 s. La probabilidad de que
// empiece depende de la hora: alta 10-13 y 15-17, baja el resto del
// horario y casi nula fuera de horario.
// ------------------------------------------------------------------
const presencias = [
    { sensorCodigo: 'SENSOR-PRESENCIA-001', peso: 1.1 }, // Paisaje al atardecer
    { sensorCodigo: 'SENSOR-PRESENCIA-002', peso: 2.8 }, // Washington (popular)
    { sensorCodigo: 'SENSOR-PRESENCIA-003', peso: 1.2 }, // Quemador de incienso
    { sensorCodigo: 'SENSOR-PRESENCIA-004', peso: 0.4 }, // Vasija baluster (menos)
    { sensorCodigo: 'SENSOR-PRESENCIA-005', peso: 1.0 }, // Estatua de gato
    { sensorCodigo: 'SENSOR-PRESENCIA-006', peso: 1.1 }, // Zun en forma de elefante
    { sensorCodigo: 'SENSOR-PRESENCIA-007', peso: 0.5 }, // Diente de megalodon (menos)
    { sensorCodigo: 'SENSOR-PRESENCIA-008', peso: 3.0 }, // Triceratops (popular)
    { sensorCodigo: 'SENSOR-PRESENCIA-009', peso: 1.0 }, // Busto de Pilato
    { sensorCodigo: 'SENSOR-PRESENCIA-010', peso: 1.1 }, // Cabeza de leon
    { sensorCodigo: 'SENSOR-PRESENCIA-011', peso: 1.2 }, // Estatua de Kefren
    { sensorCodigo: 'SENSOR-PRESENCIA-012', peso: 2.6 }  // Estatua de Ramses II (popular)
];

function probabilidadInicio(hora) {
    if (hora < 9 || hora >= 18) return 0.0005; // cerrado
    if ((hora >= 10 && hora < 13) || (hora >= 15 && hora < 17)) return 0.10; // punta
    return 0.025; // valle dentro del horario
}

for (const p of presencias) {
    const clave = 'presencia_' + p.sensorCodigo;
    const estado = context.get(clave) || { activa: false, hasta: 0 };
    let activa = estado.activa === true;
    let hasta = estado.hasta || 0;

    if (!abierto) {
        // Fuera de horario no hay visitantes: se libera cualquier presencia.
        activa = false;
        hasta = 0;
    } else if (activa) {
        if (ahoraMs >= hasta) {
            activa = false;
            hasta = 0;
        }
    } else {
        const prob = probabilidadInicio(horaEfectiva) * (p.peso / 1.5);
        if (Math.random() < prob) {
            activa = true;
            hasta = ahoraMs + entre(20, 120) * 1000; // 20 s a 2 min
        }
    }

    context.set(clave, { activa: activa, hasta: hasta });

    msgs.push({
        topic: 'museo/sensores/presencia',
        payload: {
            mensajeId: uuid(),
            sensorCodigo: p.sensorCodigo,
            presencia: activa,
            timestamp: timestamp
        }
    });
}

node.status({
    fill: 'blue',
    shape: 'dot',
    text: msgs.length + ' mensajes · ' + (horarioForzado ? '11:00 forzado' : horaEfectiva + ':00')
});
return [msgs];
